// TransformSPIMBody converts SPIM[8:248] into the recovered 240-byte CBC
// context material. Each group of four bytes is a little-endian native word.
// This transform alone does not construct a provisioning response.
func TransformSPIMBody(body [240]byte) [240]byte {
	feedback := [4]uint32{0x94189e9d, 0x2db607f2, 0xb7d56f62, 0x02be0517}
	var output [240]byte
	for i := 0; i < 15; i++ {
		var input [16]byte
		copy(input[:], body[16*i:16*i+16])
		words, next := spimRound(input, feedback)
		feedback = next
		for j, w := range words {
			for k := 0; k < 4; k++ {
				output[16*i+4*j+k] = byte(w >> (8 * k))
			}
		}
	}
	return output
}
